window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-31c0bc7a2933f838"]={"versions": [{"id": "FIG-31c0bc7a2933f838", "releases": ["R4.1.3", "R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing-Diagramm zur Veranschaulichung der verzögerten Sendestarts von CAN-Network-Management-Botschaften (CanNm) mehrerer Steuergeräte im AUTOSAR-Kommunikationsstack (Classic Platform). Das Diagramm verortet die zeitliche Entzerrung der ersten Botschaftsübertragungen nach synchroner Sendeanforderung relativ zu einer übergeordneten Botschaftsperiode.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei Steuergeräte (ECU 1, ECU 2, ECU 3), visualisiert durch farbkodierte Indikatoren (Grün: 1, Blau: 2, Gelb: 3) und entsprechende Sendeimpulse. Als Schnittstellenaufruf ist <code>(1,2,3): Nm_StartTransmission()</code> dargestellt. Zeitparameter umfassen die individuelle Startverzögerung <code>t1</code> für ECU 1, <code>t2</code> für ECU 2, <code>t3</code> für ECU 3 sowie die Zyklus-/Periodendauer <code>T</code> auf der horizontalen Zeitachse <code>time</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Zu einem gemeinsamen Trigger-Zeitpunkt erfolgt für alle drei Steuergeräte synchron der Aufruf <code>Nm_StartTransmission()</code>. Anstelle einer zeitgleichen Aussendung senden die Knoten ihre erste NM-PDU um die jeweiligen individuellen Offsets <code>t1</code>, <code>t2</code> und <code>t3</code> zeitversetzt auf den CAN-Bus. Alle drei Sendezeitpunkte liegen innerhalb des Zeitfensters der Botschaftsperiode <code>T</code> (<code>t1 &lt; t2 &lt; t3 &lt; T</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm illustriert das Verhalten zur Vermeidung von Busüberlastungen und Kollisionen (Burst-Vermeidung) beim Hochfahren oder zyklischen Starten mehrerer Knoten. Entwickler und Integratoren müssen sicherstellen, dass die konfigurierten initialen Sendeoffsets (<code>CanNmTransmissionCycleOffset</code> bzw. ECU-spezifische Startverzögerungen) so gewählt werden, dass die erste Botschaft jedes Knotens vor Ablauf der NM-Sendeperiode <code>T</code> gesendet wird und Busspitzen vermieden werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-963f6cc506561528", "releases": ["R20-11", "R21-11", "R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing-Diagramm zur Veranschaulichung der verzögerten Sendestarts von CAN-Network-Management-Botschaften (CanNm) mehrerer Steuergeräte im AUTOSAR-Kommunikationsstack (Classic Platform). Das Diagramm verortet die zeitliche Entzerrung der ersten Botschaftsübertragungen nach synchroner Sendeanforderung relativ zu einer übergeordneten Botschaftsperiode.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei Steuergeräte (ECU 1, ECU 2, ECU 3), visualisiert durch farbkodierte Indikatoren (Grün: 1, Blau: 2, Gelb: 3) und entsprechende Sendeimpulse. Als Schnittstellenaufruf ist <code>(1,2,3): Nm_StartTransmission()</code> dargestellt. Zeitparameter umfassen die individuelle Startverzögerung <code>t1</code> für ECU 1, <code>t2</code> für ECU 2, <code>t3</code> für ECU 3 sowie die Zyklus-/Periodendauer <code>T</code> auf der horizontalen Zeitachse <code>time</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Zu einem gemeinsamen Trigger-Zeitpunkt erfolgt für alle drei Steuergeräte synchron der Aufruf <code>Nm_StartTransmission()</code>. Anstelle einer zeitgleichen Aussendung senden die Knoten ihre erste NM-PDU um die jeweiligen individuellen Offsets <code>t1</code>, <code>t2</code> und <code>t3</code> zeitversetzt auf den CAN-Bus. Alle drei Sendezeitpunkte liegen innerhalb des Zeitfensters der Botschaftsperiode <code>T</code> (<code>t1 &lt; t2 &lt; t3 &lt; T</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm illustriert das Verhalten zur Vermeidung von Busüberlastungen und Kollisionen (Burst-Vermeidung) beim Hochfahren oder zyklischen Starten mehrerer Knoten. Entwickler und Integratoren müssen sicherstellen, dass die konfigurierten initialen Sendeoffsets (<code>CanNmTransmissionCycleOffset</code> bzw. ECU-spezifische Startverzögerungen) so gewählt werden, dass die erste Botschaft jedes Knotens vor Ablauf der NM-Sendeperiode <code>T</code> gesendet wird und Busspitzen vermieden werden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-31c0bc7a2933f838", "to": "FIG-963f6cc506561528", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
